#include <algorithm>
#include <iostream>
#include <stdexcept>
#include <vector>
using namespace std;

struct Stats { long long writes = 0; int maxDepth = 0; };

vector<int> mergeSort(const vector<int>& a, Stats& stats, int depth = 0) {
    stats.maxDepth = max(stats.maxDepth, depth);
    if (a.size() <= 1) return a;
    size_t middle = a.size() / 2;
    auto left = mergeSort(vector<int>(a.begin(), a.begin() + middle), stats, depth + 1);
    auto right = mergeSort(vector<int>(a.begin() + middle, a.end()), stats, depth + 1);
    vector<int> out;
    out.reserve(a.size());
    size_t i = 0, j = 0;
    while (i < left.size() && j < right.size()) {
        throw runtime_error("TODO: 选择较小的队首");
        ++stats.writes;
    }
    while (i < left.size()) { out.push_back(left[i++]); ++stats.writes; }
    while (j < right.size()) { out.push_back(right[j++]); ++stats.writes; }
    return out;
}

int main() {
    vector<vector<int>> tests = {
        {}, {7}, {2,1}, {2,2,2,2},
        {-2,3,-2,0,1}, {1,2,3,4,5}, {6,5,4,3,2,1},
        {7,2,5,1,6,3,8,4}
    };
    long long expectedWrites[] = {0,0,2,8,12,12,16,24};
    int expectedDepth[] = {0,0,1,2,3,3,3,3};
    int passed = 0;
    for (int k = 0; k < 8; ++k) {
        const auto original = tests[k];
        auto expected = original;
        sort(expected.begin(), expected.end());
        Stats stats;
        try {
            auto actual = mergeSort(tests[k], stats);
            bool ok = actual == expected && tests[k] == original
                && stats.writes == expectedWrites[k] && stats.maxDepth == expectedDepth[k];
            passed += ok;
            cout << (ok ? "PASS" : "FAIL") << " n=" << tests[k].size()
                 << " writes=" << stats.writes << " expected=" << expectedWrites[k]
                 << " depth=" << stats.maxDepth << " expected=" << expectedDepth[k] << " sorted=[";
            for (int value : actual) cout << value << ' ';
            cout << "]" << endl;
        } catch (const exception& error) {
            cout << "FAIL n=" << tests[k].size() << " error=" << error.what() << endl;
        }
    }
    cout << passed << "/8 passed" << endl;
}
